// Gera email único para evitar conflito de cadastro
var timestamp = Date.now();
pm.collectionVariables.set('emailTemp', 'usuario_' + timestamp + '@qa.com');
console.log('Email gerado:', pm.collectionVariables.get('emailTemp'));

pm.test('Status 201 - Usuário criado com sucesso', function () {
    pm.response.to.have.status(201);
});

pm.test('Response possui _id do novo usuário', function () {
    var json = pm.response.json();
    pm.expect(json).to.have.property('_id');
    // Salva o ID para usar nos próximos requests
    pm.collectionVariables.set('usuarioId', json._id);
    console.log('✅ usuarioId salvo:', json._id);
});

pm.test('Mensagem de cadastro correto', function () {
    var json = pm.response.json();
    pm.expect(json.message).to.eql('Cadastro realizado com sucesso');
});

